/**
 *
 * DialogPopup is a component that displays the popup content of a dialog.
 *
 * [Live Demo](https://www.primereact.org/dialog/)
 *
 * @module DialogPopup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseMotionProps } from '@primereact/types/headless/motion';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DialogRootInstance } from './DialogRoot.types';
/**
 * Defines passthrough(pt) options type in DialogPopup component.
 */
export type DialogPopupPassThroughType<E> = PassThroughType<DialogPopupInstance, E>;
/**
 * Defines passthrough(pt) options of DialogPopup component.
 */
export interface DialogPopupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DialogPopupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DialogPopup component.
 */
export interface DialogPopupProps extends BaseComponentProps<DialogPopupInstance, unknown, DialogPopupPassThrough> {
    /**
     * Used to apply motion to the popup element. It accepts the same properties as useMotion hook.
     */
    motionProps?: UseMotionProps | undefined;
}
/**
 * Defines valid state in DialogPopup component.
 */
export interface DialogPopupState {
}
/**
 * Defines the methods and properties exposed by DialogPopup component.
 */
export interface DialogPopupExposes {
    /**
     * The Dialog component instance.
     */
    dialog: DialogRootInstance | undefined | null;
}
/**
 * Instance of DialogPopup component.
 */
export type DialogPopupInstance = ComponentInstance<DialogPopupProps, DialogPopupState, DialogPopupExposes>;
